}

class Game {
    private final Board board = new Board();
    private Color currentTurn = Color.WHITE;
    private final List<Move> history = new ArrayList<>();
    private GameState state = GameState.IN_PROGRESS;

    public Game() {
        board.setupStartingPosition();
    }

    // ── makeMove ─────────────────────────
    public MoveResult makeMove(Position from, Position to) {
        if (state != GameState.IN_PROGRESS && state != GameState.CHECK)
            throw new IllegalStateException("Game is over");

        Piece piece = board.getPiece(from);
        if (piece == null)
            throw new InvalidMoveException("No piece at " + from);
        if (piece.getColor() != currentTurn)
            throw new WrongTurnException("It's " + currentTurn + "'s turn");

        // Validate: is `to` in the piece's legal moves?
        List<Position> valid = piece.getValidMoves(board, from);
        if (!valid.contains(to))
            throw new InvalidMoveException(piece + " cannot move from " + from + " to " + to);

        // Simulate move: would it leave own king in check?
        Piece captured = board.getPiece(to);
        board.movePiece(from, to);

        if (isInCheck(currentTurn)) {
            // Rollback — illegal move
            board.setPiece(from, piece);
            board.setPiece(to, captured);
            piece.hasMoved = false;  // reset (simplification)
            throw new KingInCheckException("Move would leave own king in check");
        }

        // Commit — record history, switch turns, check game state
        history.add(new Move(from, to, piece, captured, MoveType.NORMAL));
        currentTurn = currentTurn.opposite();

        // Detect opponent's game state after this move
        if (isCheckmate(currentTurn)) {
            state = GameState.CHECKMATE;
        } else if (isStalemate(currentTurn)) {
            state = GameState.STALEMATE;
        } else if (isInCheck(currentTurn)) {
            state = GameState.CHECK;
        } else {
            state = GameState.IN_PROGRESS;
        }

        return new MoveResult(state, captured);
    }

    // ── Check detection ─────────────────
    public boolean isInCheck(Color color) {
        Position kingPos = board.findKing(color);
        return board.isUnderAttack(kingPos, color.opposite());
    }

    // ── Checkmate = in check + no legal move saves the king ──
    public boolean isCheckmate(Color color) {
        if (!isInCheck(color)) return false;
        return !hasAnyLegalMove(color);
    }

    // ── Stalemate = not in check + no legal moves ──
    public boolean isStalemate(Color color) {
        if (isInCheck(color)) return false;
        return !hasAnyLegalMove(color);
    }

    // Iterate all pieces, try all their moves, simulate — any that escape check?
    private boolean hasAnyLegalMove(Color color) {
        for (int r = 0; r < 8; r++) {
            for (int c = 0; c < 8; c++) {
                Piece p = board.getPiece(new Position(r, c));
                if (p == null || p.getColor() != color) continue;
                Position from = new Position(r, c);
                for (Position to : p.getValidMoves(board, from)) {
                    // Simulate
                    Piece captured = board.getPiece(to);
                    board.movePiece(from, to);
                    boolean stillInCheck = isInCheck(color);
                    // Rollback
                    board.setPiece(from, p);
                    board.setPiece(to, captured);
                    if (!stillInCheck) return true;
                }
            }
        }
        return false;
    }

    public GameState getState() { return state; }
    public Color getCurrentTurn() { return currentTurn; }
    public List<Move> getHistory() { return Collections.unmodifiableList(history); }
}

record MoveResult(GameState state, Piece captured) {}
